  metrics.gauge('genai.rag.latency.vector_search', searchTime);
  metrics.gauge('genai.rag.latency.llm_response', llmTime);

  return {
    response: llmResponse,
    metrics: {
      totalTime,
      embeddingTime,
      searchTime,
      llmTime
    }
  };
